import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { fireEvent, render, screen } from "../../../test-utils/render";
import MagneticField from "../index";

type MatchMediaOptions = {
  hover?: boolean;
  reducedMotion?: boolean;
};

type MockMediaQueryList = {
  addEventListener: (type: string, handler: () => void) => void;
  addListener: () => void;
  dispatchEvent: () => boolean;
  matches: boolean;
  media: string;
  onchange: null;
  removeEventListener: () => void;
  removeListener: () => void;
  _changeHandler?: () => void;
};

// `motion`'s useReducedMotion() reads window.matchMedia("(prefers-reduced-motion)")
// exactly once per process (module-level singleton in motion-dom), the first time
// any component in this file calls the hook, and only ever updates afterwards via
// a "change" event dispatched on that original MediaQueryList. Reassigning
// window.matchMedia in a later test has no effect on that cached value, so we
// capture the very first reduced-motion query object here and, when a test needs
// reduced motion to be "on", flip its `matches` flag and invoke the handler
// motion-dom itself registered.
let reducedMotionRecord: MockMediaQueryList | null = null;

const mockMatchMedia = ({
  hover = false,
  reducedMotion = false,
}: MatchMediaOptions = {}) => {
  window.matchMedia = vi.fn().mockImplementation((query: string) => {
    const isReducedMotionQuery = query.includes("prefers-reduced-motion");
    const record: MockMediaQueryList = {
      addEventListener: (type, handler) => {
        if (type === "change") {
          record._changeHandler = handler;
        }
      },
      addListener: () => {},
      dispatchEvent: () => false,
      matches: isReducedMotionQuery ? reducedMotion : hover,
      media: query,
      onchange: null,
      removeEventListener: () => {},
      removeListener: () => {},
    };
    if (isReducedMotionQuery && !reducedMotionRecord) {
      reducedMotionRecord = record;
    }
    return record;
  });
};

const forceReducedMotion = () => {
  if (!reducedMotionRecord) {
    throw new Error(
      "reducedMotionRecord was never captured; render a MagneticField first"
    );
  }
  reducedMotionRecord.matches = true;
  reducedMotionRecord._changeHandler?.();
};

let frameQueue: FrameRequestCallback[];

const stubRaf = () => {
  frameQueue = [];
  vi.stubGlobal(
    "requestAnimationFrame",
    vi.fn((cb: FrameRequestCallback) => {
      frameQueue.push(cb);
      return frameQueue.length;
    })
  );
  vi.stubGlobal("cancelAnimationFrame", vi.fn());
};

// Runs whatever frames are currently queued, `count` times in sequence, each
// `stepMs` further along the clock. The physics integrator needs at least
// two ticks before velocity/position actually move (the first tick only
// seeds `lastFrameRef`), so tests generally advance several frames.
const advanceFrames = (count: number, stepMs = 16) => {
  let time = 0;
  for (let i = 0; i < count; i++) {
    time += stepMs;
    const pending = frameQueue.splice(0, frameQueue.length);
    for (const cb of pending) {
      cb(time);
    }
  }
};

describe("MagneticField", () => {
  beforeEach(() => {
    stubRaf();
    mockMatchMedia({ hover: true });
  });

  afterEach(() => {
    vi.unstubAllGlobals();
    vi.restoreAllMocks();
  });

  it("renders without throwing", () => {
    const { container } = render(
      <MagneticField>
        <button type="button">Item</button>
      </MagneticField>
    );
    expect(container).toBeInTheDocument();
  });

  it("renders in repel mode", () => {
    const { container } = render(
      <MagneticField mode="repel">
        <button type="button">Item</button>
      </MagneticField>
    );
    expect(container).toBeInTheDocument();
  });

  it("discovers data-magnetic descendants and moves them toward the pointer in attract mode", () => {
    const { container } = render(
      <MagneticField mode="attract">
        <button data-magnetic type="button">
          Item
        </button>
      </MagneticField>
    );
    const root = container.firstChild as HTMLElement;
    const button = screen.getByRole("button");

    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    const match = button.style.transform.match(
      /translate3d\(([-\d.]+)px, ([-\d.]+)px, 0\)/
    );
    expect(match).not.toBeNull();
    const [, x, y] = match as RegExpMatchArray;
    // Attract pulls the element in the same direction as the pointer offset.
    expect(Number(x)).toBeGreaterThan(0);
    expect(Number(y)).toBeGreaterThan(0);
  });

  it("moves discovered participants away from the pointer in repel mode", () => {
    const { container } = render(
      <MagneticField mode="repel">
        <button data-magnetic type="button">
          Item
        </button>
      </MagneticField>
    );
    const root = container.firstChild as HTMLElement;
    const button = screen.getByRole("button");

    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    const match = button.style.transform.match(
      /translate3d\(([-\d.]+)px, ([-\d.]+)px, 0\)/
    );
    expect(match).not.toBeNull();
    const [, x, y] = match as RegExpMatchArray;
    // Repel pushes the element away from the pointer (opposite sign).
    expect(Number(x)).toBeLessThan(0);
    expect(Number(y)).toBeLessThan(0);
  });

  it("applies a tangential offset in orbit mode that differs from a plain attract pull", () => {
    const { container } = render(
      <MagneticField mode="orbit">
        <button data-magnetic type="button">
          Item
        </button>
      </MagneticField>
    );
    const root = container.firstChild as HTMLElement;
    const button = screen.getByRole("button");

    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    const match = button.style.transform.match(
      /translate3d\(([-\d.]+)px, ([-\d.]+)px, 0\)/
    );
    expect(match).not.toBeNull();
    const [, x, y] = match as RegExpMatchArray;
    // Orbit combines a radial pull with a tangential swirl: for this pointer
    // offset the tangential term dominates and flips the sign of each axis
    // relative to a plain attract pull (which would be positive/positive).
    expect(Number(x)).toBeLessThan(0);
    expect(Number(y)).toBeGreaterThan(0);
  });

  it("discovers participants supplied via the items prop and moves their wrapper", () => {
    render(
      <MagneticField
        items={[
          {
            element: <button type="button">Orb</button>,
            id: "orb",
          },
        ]}
        mode="attract"
      >
        <div />
      </MagneticField>
    );

    const button = screen.getByRole("button", { name: "Orb" });
    const wrapper = button.parentElement as HTMLElement;
    const root = wrapper.parentElement as HTMLElement;

    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    expect(wrapper.style.transform).not.toBe("");
  });

  it("does nothing while paused, leaving participants at rest", () => {
    const { container } = render(
      <MagneticField mode="attract" paused>
        <button data-magnetic type="button">
          Item
        </button>
      </MagneticField>
    );
    const root = container.firstChild as HTMLElement;
    const button = screen.getByRole("button");

    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    expect(button.style.transform).toBe(
      "translate3d(0px, 0px, 0) rotate(0deg)"
    );
  });

  // NOTE: this test permanently flips motion's cached reduced-motion
  // singleton for the rest of this file (see the comment above
  // `reducedMotionRecord`), so it must stay last in this describe block.
  it("ignores pointer movement entirely once reduced motion is preferred", () => {
    forceReducedMotion();

    const { container } = render(
      <MagneticField mode="attract">
        <button data-magnetic type="button">
          Item
        </button>
      </MagneticField>
    );
    const root = container.firstChild as HTMLElement;
    const button = screen.getByRole("button");

    // The pointer-tracking effect never attaches its listeners in this mode,
    // so this pointermove is a no-op and the participant stays at rest even
    // after frames run.
    fireEvent.pointerMove(root, { clientX: 30, clientY: 40 });
    advanceFrames(6);

    expect(button.style.transform).toBe(
      "translate3d(0px, 0px, 0) rotate(0deg)"
    );
  });
});

describe("MagneticField accessibility", () => {
  it("has no accessibility violations", async () => {
    const { container } = render(
      <MagneticField>
        <button type="button">Item</button>
      </MagneticField>
    );
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });
});

"use client";

import { cn } from "@repo/smoothui-utils";
import {
  type MotionValue,
  motion,
  motionValue,
  useReducedMotion,
} from "motion/react";
import type { ReactElement, ReactNode } from "react";
import { useEffect, useRef, useState } from "react";

export type MagneticFieldMode = "attract" | "repel" | "orbit";

export type MagneticFieldItem = {
  element: ReactElement;
  id: string;
};

export type MagneticFieldProps = {
  children?: ReactNode;
  className?: string;
  damping?: number;
  items?: MagneticFieldItem[];
  mode?: MagneticFieldMode;
  paused?: boolean;
  radius?: number;
  rotate?: boolean;
  stiffness?: number;
  strength?: number;
};

type ParticipantState = {
  centerX: number;
  centerY: number;
  rotate: MotionValue<number>;
  vr: number;
  vx: number;
  vy: number;
  x: MotionValue<number>;
  y: MotionValue<number>;
};

const DEFAULT_RADIUS = 160;
const DEFAULT_STRENGTH = 0.35;
const DEFAULT_STIFFNESS = 180;
const DEFAULT_DAMPING = 18;
const MAX_ROTATE_DEG = 18;
const FALLOFF_POWER = 2;
const MAX_DELTA_SECONDS = 0.05;
const ORBIT_RADIAL_FACTOR = 0.2;
const ORBIT_TANGENTIAL_FACTOR = 0.4;
const MAGNETIC_SELECTOR = "[data-magnetic]";

const clamp = (value: number, min: number, max: number) =>
  Math.min(max, Math.max(min, value));

const computeFalloff = (distance: number, radius: number) => {
  if (distance >= radius) {
    return 0;
  }
  return (1 - distance / radius) ** FALLOFF_POWER;
};

const computeOffset = (
  dx: number,
  dy: number,
  distance: number,
  falloff: number,
  strength: number,
  mode: MagneticFieldMode
): { x: number; y: number } => {
  if (distance === 0) {
    return { x: 0, y: 0 };
  }
  const directional = mode === "repel" ? -Math.abs(strength) : strength;
  if (mode === "orbit") {
    const tangentX = -dy / distance;
    const tangentY = dx / distance;
    const pull = directional * falloff * distance * ORBIT_TANGENTIAL_FACTOR;
    return {
      x: dx * directional * falloff * ORBIT_RADIAL_FACTOR + tangentX * pull,
      y: dy * directional * falloff * ORBIT_RADIAL_FACTOR + tangentY * pull,
    };
  }
  return { x: dx * directional * falloff, y: dy * directional * falloff };
};

const createParticipant = (): ParticipantState => ({
  centerX: 0,
  centerY: 0,
  rotate: motionValue(0),
  vr: 0,
  vx: 0,
  vy: 0,
  x: motionValue(0),
  y: motionValue(0),
});

const resetParticipant = (state: ParticipantState) => {
  state.x.set(0);
  state.y.set(0);
  state.rotate.set(0);
  state.vx = 0;
  state.vy = 0;
  state.vr = 0;
};

const MagneticField = ({
  children,
  className,
  damping = DEFAULT_DAMPING,
  items,
  mode = "attract",
  paused = false,
  radius = DEFAULT_RADIUS,
  rotate = false,
  stiffness = DEFAULT_STIFFNESS,
  strength = DEFAULT_STRENGTH,
}: MagneticFieldProps) => {
  const shouldReduceMotion = useReducedMotion();
  const [isPointerCapable, setIsPointerCapable] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const pointerRef = useRef<{ x: number; y: number } | null>(null);
  const participantsRef = useRef<Map<string, ParticipantState>>(new Map());
  const nodeMapRef = useRef<Map<string, HTMLElement>>(new Map());
  const elementsRef = useRef<Map<HTMLElement, ParticipantState>>(new Map());
  const rafRef = useRef<number | null>(null);
  const lastFrameRef = useRef<number | null>(null);

  useEffect(() => {
    const mediaQuery = window.matchMedia("(hover: hover) and (pointer: fine)");
    setIsPointerCapable(mediaQuery.matches);
    const handleChange = (event: MediaQueryListEvent) => {
      setIsPointerCapable(event.matches);
    };
    mediaQuery.addEventListener("change", handleChange);
    return () => mediaQuery.removeEventListener("change", handleChange);
  }, []);

  const isEffectDisabled = paused || shouldReduceMotion || !isPointerCapable;

  const getOrCreateParticipant = (id: string): ParticipantState => {
    let state = participantsRef.current.get(id);
    if (!state) {
      state = createParticipant();
      participantsRef.current.set(id, state);
    }
    return state;
  };

  // Prune stale participants when the `items` list changes shape.
  useEffect(() => {
    if (!items) {
      participantsRef.current.clear();
      nodeMapRef.current.clear();
      return;
    }
    const ids = new Set(items.map((item) => item.id));
    for (const key of Array.from(participantsRef.current.keys())) {
      if (!ids.has(key)) {
        participantsRef.current.delete(key);
        nodeMapRef.current.delete(key);
      }
    }
  }, [items]);

  // Measure rest positions for `items` participants once per layout change.
  useEffect(() => {
    if (!items) {
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const measure = () => {
      const containerRect = container.getBoundingClientRect();
      for (const [id, node] of nodeMapRef.current) {
        const state = participantsRef.current.get(id);
        if (!state) {
          continue;
        }
        const rect = node.getBoundingClientRect();
        state.centerX = rect.left + rect.width / 2 - containerRect.left;
        state.centerY = rect.top + rect.height / 2 - containerRect.top;
      }
    };

    measure();
    const resizeObserver = new ResizeObserver(measure);
    for (const node of nodeMapRef.current.values()) {
      resizeObserver.observe(node);
    }
    window.addEventListener("resize", measure);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", measure);
    };
  }, [items]);

  // Discover and measure `data-magnetic` descendants of `children`.
  useEffect(() => {
    if (items) {
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const syncElements = () => {
      const found = Array.from(
        container.querySelectorAll<HTMLElement>(MAGNETIC_SELECTOR)
      );
      const map = elementsRef.current;
      for (const el of Array.from(map.keys())) {
        if (!found.includes(el)) {
          el.style.transform = "";
          el.style.willChange = "";
          map.delete(el);
        }
      }
      const containerRect = container.getBoundingClientRect();
      for (const el of found) {
        if (!map.has(el)) {
          el.style.willChange = "transform";
          map.set(el, createParticipant());
        }
        const state = map.get(el);
        if (!state) {
          continue;
        }
        const rect = el.getBoundingClientRect();
        state.centerX = rect.left + rect.width / 2 - containerRect.left;
        state.centerY = rect.top + rect.height / 2 - containerRect.top;
      }
    };

    syncElements();
    const mutationObserver = new MutationObserver(syncElements);
    mutationObserver.observe(container, { childList: true, subtree: true });
    const resizeObserver = new ResizeObserver(syncElements);
    resizeObserver.observe(container);
    window.addEventListener("resize", syncElements);

    return () => {
      mutationObserver.disconnect();
      resizeObserver.disconnect();
      window.removeEventListener("resize", syncElements);
      for (const el of elementsRef.current.keys()) {
        el.style.transform = "";
        el.style.willChange = "";
      }
    };
  }, [items]);

  // Track the pointer position relative to the container with one listener.
  useEffect(() => {
    if (isEffectDisabled) {
      pointerRef.current = null;
      return;
    }
    const container = containerRef.current;
    if (!container) {
      return;
    }

    const handlePointerMove = (event: PointerEvent) => {
      const rect = container.getBoundingClientRect();
      pointerRef.current = {
        x: event.clientX - rect.left,
        y: event.clientY - rect.top,
      };
    };
    const handlePointerLeave = () => {
      pointerRef.current = null;
    };

    container.addEventListener("pointermove", handlePointerMove, {
      passive: true,
    });
    container.addEventListener("pointerleave", handlePointerLeave, {
      passive: true,
    });

    return () => {
      container.removeEventListener("pointermove", handlePointerMove);
      container.removeEventListener("pointerleave", handlePointerLeave);
    };
  }, [isEffectDisabled]);

  // Single rAF loop driving a manual spring integrator per participant.
  useEffect(() => {
    if (isEffectDisabled) {
      for (const state of participantsRef.current.values()) {
        resetParticipant(state);
      }
      for (const [el, state] of elementsRef.current) {
        resetParticipant(state);
        el.style.transform = "translate3d(0px, 0px, 0) rotate(0deg)";
      }
      return;
    }

    const applyPhysics = (state: ParticipantState, dt: number) => {
      const pointer = pointerRef.current;
      let targetX = 0;
      let targetY = 0;
      let targetRotate = 0;

      if (pointer) {
        const dx = pointer.x - state.centerX;
        const dy = pointer.y - state.centerY;
        const distance = Math.hypot(dx, dy);
        const falloff = computeFalloff(distance, radius);
        if (falloff > 0) {
          const offset = computeOffset(
            dx,
            dy,
            distance,
            falloff,
            strength,
            mode
          );
          targetX = offset.x;
          targetY = offset.y;
          if (rotate) {
            targetRotate = clamp(
              ((Math.atan2(dy, dx) * 180) / Math.PI) * falloff,
              -MAX_ROTATE_DEG,
              MAX_ROTATE_DEG
            );
          }
        }
      }

      const currentX = state.x.get();
      const currentY = state.y.get();
      const currentRotate = state.rotate.get();

      state.vx += ((targetX - currentX) * stiffness - state.vx * damping) * dt;
      state.vy += ((targetY - currentY) * stiffness - state.vy * damping) * dt;
      state.vr +=
        ((targetRotate - currentRotate) * stiffness - state.vr * damping) * dt;

      state.x.set(currentX + state.vx * dt);
      state.y.set(currentY + state.vy * dt);
      state.rotate.set(currentRotate + state.vr * dt);
    };

    const step = (time: number) => {
      const last = lastFrameRef.current ?? time;
      const dt = clamp((time - last) / 1000, 0, MAX_DELTA_SECONDS);
      lastFrameRef.current = time;

      for (const state of participantsRef.current.values()) {
        applyPhysics(state, dt);
      }
      for (const [el, state] of elementsRef.current) {
        applyPhysics(state, dt);
        const x = state.x.get();
        const y = state.y.get();
        const r = state.rotate.get();
        el.style.transform = `translate3d(${x}px, ${y}px, 0) rotate(${r}deg)`;
      }

      rafRef.current = requestAnimationFrame(step);
    };

    rafRef.current = requestAnimationFrame(step);

    return () => {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
      }
      lastFrameRef.current = null;
    };
  }, [damping, isEffectDisabled, mode, radius, rotate, stiffness, strength]);

  const content = items
    ? items.map((item) => {
        const state = getOrCreateParticipant(item.id);
        return (
          <motion.div
            className="inline-block will-change-transform"
            key={item.id}
            ref={(node: HTMLDivElement | null) => {
              if (node) {
                nodeMapRef.current.set(item.id, node);
              } else {
                nodeMapRef.current.delete(item.id);
              }
            }}
            style={{ rotate: state.rotate, x: state.x, y: state.y }}
          >
            {item.element}
          </motion.div>
        );
      })
    : children;

  return (
    <div className={cn("relative", className)} ref={containerRef}>
      {content}
    </div>
  );
};

export default MagneticField;

