export default function NumberField({
  "aria-label": ariaLabel,
  className,
  defaultValue = 0,
  disabled,
  label,
  max,
  min,
  name,
  onValueChange,
  step = 1,
  value: valueProp,
}: NumberFieldProps) {
  const id = useId();
  const [uncontrolled, setUncontrolled] = useState(defaultValue);
  const isControlled = valueProp !== undefined;
  const value = isControlled ? (valueProp ?? 0) : uncontrolled;

  const commit = useCallback(
    (next: number) => {
      let clamped = next;
      if (typeof min === "number") {
        clamped = Math.max(min, clamped);
      }
      if (typeof max === "number") {
        clamped = Math.min(max, clamped);
      }
      if (!isControlled) {
        setUncontrolled(clamped);
      }
      onValueChange?.(clamped);
    },
    [isControlled, max, min, onValueChange]
  );

  return (
    <NumberFieldRoot className={className}>
      {label ? (
        <NumberFieldScrubArea>
          <label className="font-medium text-sm leading-none" htmlFor={id}>
            {label}
          </label>
        </NumberFieldScrubArea>
      ) : null}
      <NumberFieldGroup>
        <NumberFieldDecrement
          aria-label="Decrement"
          disabled={disabled}
          onClick={() => commit(value - step)}
        />
        <NumberFieldInput
          aria-label={label ? undefined : ariaLabel}
          disabled={disabled}
          id={id}
          max={max}
          min={min}
          name={name}
          onChange={(event) => {
            const next = event.target.valueAsNumber;
            commit(Number.isFinite(next) ? next : 0);
          }}
          step={step}
          value={value}
        />
        <NumberFieldIncrement
          aria-label="Increment"
          disabled={disabled}
          onClick={() => commit(value + step)}
        />
      </NumberFieldGroup>
    </NumberFieldRoot>
  );
}

