import { afterEach, expect, it, vi } from "vitest";
import { cleanup, fireEvent, render } from "../../../test-utils/render";
import NumberFlow from "../index";

afterEach(() => {
  cleanup();
  vi.restoreAllMocks();
});

it("restarts changed digit animations and cancels them on unmount", () => {
  const cancel = vi.fn();
  const animate = vi.fn(() => ({ cancel }));
  vi.stubGlobal("Animation", class {});
  Object.defineProperty(Element.prototype, "animate", {
    configurable: true,
    value: animate,
  });
  const { getByRole, unmount } = render(<NumberFlow />);
  expect(animate).not.toHaveBeenCalled();
  fireEvent.click(getByRole("button", { name: "Increase number" }));
  expect(animate).toHaveBeenCalledTimes(2);
  fireEvent.click(getByRole("button", { name: "Increase number" }));
  expect(cancel).toHaveBeenCalledTimes(2);
  expect(animate).toHaveBeenCalledTimes(4);
  unmount();
  expect(cancel).toHaveBeenCalledTimes(4);
  Reflect.deleteProperty(Element.prototype, "animate");
  vi.unstubAllGlobals();
});

it("carries across digits and respects both limits", () => {
  const { getByRole, rerender } = render(
    <NumberFlow max={100} min={99} value={99} />
  );
  expect(getByRole("button", { name: "Decrease number" })).toBeDisabled();
  rerender(<NumberFlow max={100} min={99} value={100} />);
  expect(getByRole("status", { name: "Current value" })).toHaveTextContent(
    "100"
  );
  expect(getByRole("button", { name: "Increase number" })).toBeDisabled();
  rerender(<NumberFlow value={0} />);
  expect(getByRole("button", { name: "Decrease number" })).toBeDisabled();
  rerender(<NumberFlow value={999} />);
  expect(getByRole("button", { name: "Increase number" })).toBeDisabled();
});

it("keeps the same controls and static digits with reduced motion", () => {
  vi.spyOn(window, "matchMedia").mockReturnValue({
    addEventListener: vi.fn(),
    matches: true,
    removeEventListener: vi.fn(),
  } as unknown as MediaQueryList);
  const animate = vi.fn();
  Object.defineProperty(Element.prototype, "animate", {
    configurable: true,
    value: animate,
  });
  const { getByRole } = render(<NumberFlow />);
  fireEvent.click(getByRole("button", { name: "Increase number" }));
  expect(getByRole("status", { name: "Current value" })).toHaveTextContent("1");
  expect(animate).not.toHaveBeenCalled();
  Reflect.deleteProperty(Element.prototype, "animate");
});

import { describe, expect, it, vi } from "vitest";
import { axe } from "vitest-axe";
import { fireEvent, render } from "../../../test-utils/render";
import NumberFlow from "../index";

describe("NumberFlow", () => {
  it("renders without throwing", () => {
    const { container } = render(<NumberFlow />);
    expect(container).toBeInTheDocument();
  });

  it("has no accessibility violations", async () => {
    const { container } = render(<NumberFlow />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("does not collapse rapid controlled increments to the same value", () => {
    const onChange = vi.fn();
    const { getByRole } = render(
      <NumberFlow onChange={onChange} value={128} />
    );
    const increase = getByRole("button", { name: "Increase number" });
    fireEvent.click(increase);
    fireEvent.click(increase);
    expect(onChange.mock.calls.map((call) => call[0])).toEqual([129, 130]);
  });
});

"use client";

import SmoothButton from "@repo/smoothui/components/smooth-button";
import { cn } from "@repo/smoothui-utils";
import { Minus, Plus } from "lucide-react";
import { useEffect, useRef, useState } from "react";

const TENS_PLACE = 10;
const HUNDREDS_PLACE = 100;

const animateDigit = (
  previous: HTMLElement | null,
  next: HTMLElement | null,
  increasing: boolean
): Animation[] => {
  if (!(previous?.animate && next?.animate)) {
    return [];
  }
  const options = { duration: 300, easing: "cubic-bezier(0.22, 1, 0.36, 1)" };
  return [
    previous.animate(
      [
        { opacity: 1, transform: "translateY(0%)" },
        { opacity: 0, transform: `translateY(${increasing ? -100 : 100}%)` },
      ],
      options
    ),
    next.animate(
      [
        { opacity: 0, transform: `translateY(${increasing ? 100 : -100}%)` },
        { opacity: 1, transform: "translateY(0%)" },
      ],
      options
    ),
  ];
};

export interface NumberFlowProps {
  buttonClassName?: string;
  className?: string;
  digitClassName?: string;
  max?: number;
  min?: number;
  onChange?: (value: number) => void;
  value?: number;
}

export default function NumberFlow({
  value: controlledValue,
  onChange,
  min = 0,
  max = 999,
  className = "",
  digitClassName = "",
  buttonClassName = "",
}: NumberFlowProps) {
  const [internalValue, setInternalValue] = useState(0);
  const [prevValue, setPrevValue] = useState(controlledValue ?? 0);
  const [reduced, setReduced] = useState(false);

  const value = controlledValue === undefined ? internalValue : controlledValue;
  const lastAnimatedValue = useRef(value);
  // Optimistic cursor for rapid clicks. Only follow the prop when the parent
  // (or internal state) actually catches up — never reset mid-click from a
  // re-render that still sees the previous controlled value.
  const committedValue = useRef(value);

  useEffect(() => {
    committedValue.current = value;
  }, [value]);

  const prevValueRef = useRef<HTMLElement>(null);
  const nextValueRef = useRef<HTMLElement>(null);
  const prevValueTens = useRef<HTMLElement>(null);
  const nextValueTens = useRef<HTMLElement>(null);
  const prevValueHunds = useRef<HTMLElement>(null);
  const nextValueHunds = useRef<HTMLElement>(null);

  const setValue = (val: number) => {
    committedValue.current = val;
    if (onChange) {
      onChange(val);
    }
    if (controlledValue === undefined) {
      setInternalValue(val);
    }
  };

  const add = () => {
    const { current } = committedValue;
    if (current < max) {
      setPrevValue(current);
      setValue(current + 1);
    }
  };

  const subtract = () => {
    const { current } = committedValue;
    if (current > min) {
      setPrevValue(current);
      setValue(current - 1);
    }
  };

  useEffect(() => {
    const media = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(media.matches);
    update();
    media.addEventListener("change", update);
    return () => media.removeEventListener("change", update);
  }, []);

  useEffect(() => {
    const changed = lastAnimatedValue.current !== value;
    lastAnimatedValue.current = value;
    if (
      !changed ||
      reduced ||
      window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
      value === prevValue
    ) {
      return;
    }
    const animations: Animation[] = [];
    const digits = [
      { next: nextValueRef.current, place: 1, previous: prevValueRef.current },
      {
        next: nextValueTens.current,
        place: TENS_PLACE,
        previous: prevValueTens.current,
      },
      {
        next: nextValueHunds.current,
        place: HUNDREDS_PLACE,
        previous: prevValueHunds.current,
      },
    ];
    for (const digit of digits) {
      if (
        Math.floor(value / digit.place) % TENS_PLACE !==
        Math.floor(prevValue / digit.place) % TENS_PLACE
      ) {
        animations.push(
          ...animateDigit(digit.previous, digit.next, value > prevValue)
        );
      }
    }
    return () => {
      for (const animation of animations) {
        animation.cancel();
      }
    };
  }, [value, prevValue, reduced]);

  return (
    <div
      className={cn(
        "flex flex-col items-center justify-center gap-8",
        className
      )}
    >
      <div className="flex items-center gap-2 rounded-xl border bg-background p-4">
        <output aria-label="Current value" className="sr-only">
          {value}
        </output>
        <div
          aria-hidden="true"
          className={cn("flex items-center gap-1", digitClassName)}
        >
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueHunds}
              style={{ transform: "translateY(-100%)" }}
            >
              {Math.floor(prevValue / HUNDREDS_PLACE)}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueHunds}
              style={{ transform: "translateY(0%)" }}
            >
              {Math.floor(value / HUNDREDS_PLACE)}
            </span>
          </div>
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueTens}
              style={{ transform: "translateY(-100%)" }}
            >
              {Math.floor(prevValue / TENS_PLACE) % TENS_PLACE}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueTens}
              style={{ transform: "translateY(0%)" }}
            >
              {Math.floor(value / TENS_PLACE) % TENS_PLACE}
            </span>
          </div>
          <div
            className={cn(
              "relative h-16 w-12 overflow-hidden rounded-lg border bg-primary"
            )}
          >
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={prevValueRef}
              style={{ transform: "translateY(-100%)" }}
            >
              {prevValue % TENS_PLACE}
            </span>
            <span
              className="absolute inset-0 flex items-center justify-center font-semibold text-2xl text-foreground"
              ref={nextValueRef}
              style={{ transform: "translateY(0%)" }}
            >
              {value % TENS_PLACE}
            </span>
          </div>
        </div>

        <div className="flex flex-col gap-1 self-stretch">
          <SmoothButton
            aria-label="Increase number"
            className={cn(
              "h-auto min-h-0 flex-1 overflow-hidden",
              buttonClassName
            )}
            disabled={value >= max}
            onClick={add}
            size="icon-sm"
            type="button"
            variant="outline"
          >
            <Plus className="h-3 w-3" />
          </SmoothButton>
          <SmoothButton
            aria-label="Decrease number"
            className={cn(
              "h-auto min-h-0 flex-1 overflow-hidden",
              buttonClassName
            )}
            disabled={value <= min}
            onClick={subtract}
            size="icon-sm"
            type="button"
            variant="outline"
          >
            <Minus className="h-3 w-3" />
          </SmoothButton>
        </div>
      </div>
    </div>
  );
}

